args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 4) stop("expected input, output, study family, outcome structure")
d <- read.csv(args[[1]], stringsAsFactors = FALSE, check.names = TRUE, na.strings = "__MIMIC_INTERNAL_MISSING__")
family <- args[[3]]; outcome_structure <- args[[4]]
required_fields <- if (family == "prediction") c("analysis_id", "outcome") else c("analysis_id", "exposure", "outcome")
if (!all(required_fields %in% names(d))) stop("missing required analysis fields")
as_binary <- function(x) { if (is.logical(x)) return(as.integer(x)); if (is.numeric(x)) return(as.integer(x != 0)); values <- tolower(as.character(x)); ifelse(values %in% c("1","true","yes","y"),1,ifelse(values %in% c("0","false","no","n"),0,NA)) }
numeric_columns <- setdiff(names(d)[vapply(d, is.numeric, logical(1))], c("outcome"))
d$outcome <- if (outcome_structure == "binary") as_binary(d$outcome) else as.numeric(d$outcome)
exposure_is_binary <- "exposure" %in% names(d) && length(unique(na.omit(d$exposure))) == 2
if ("exposure" %in% names(d)) d$exposure <- if (exposure_is_binary) as_binary(d$exposure) else as.numeric(d$exposure)
candidate_columns <- intersect(c("exposure", grep("^(predictor|covariate|effect_modifier)_", names(d), value=TRUE)), names(d))
category_labels <- list()
for (name in candidate_columns) if (!is.numeric(d[[name]])) { category_labels[[name]] <- levels(as.factor(d[[name]])); d[[name]] <- as.numeric(as.factor(d[[name]])) - 1 }
effect_modifier_columns <- grep("^effect_modifier_", candidate_columns, value=TRUE)
if (any(vapply(effect_modifier_columns, function(name) length(unique(na.omit(d[[name]]))) < 2, logical(1)))) stop("effect modifier requires at least two observed levels")
ordinary_adjustment_columns <- grep("^(predictor|covariate)_", candidate_columns, value=TRUE)
zero_variance_adjustments <- ordinary_adjustment_columns[vapply(ordinary_adjustment_columns, function(name) length(unique(na.omit(d[[name]]))) < 2, logical(1))]
candidate_columns <- setdiff(candidate_columns, zero_variance_adjustments)
complete <- complete.cases(d[, c("outcome", candidate_columns), drop=FALSE]); x <- d[complete, , drop=FALSE]
if (nrow(x) < 20) stop("insufficient complete records")
emit <- function(name, value) cat(name, "\t", value, "\n", sep="", file=args[[2]], append=TRUE)
file.create(args[[2]]); emit("r_version", paste(R.version$major,R.version$minor,sep=".")); emit("family", family); emit("total", nrow(d)); emit("complete", nrow(x)); emit("missing", nrow(d)-nrow(x)); emit("events", if(outcome_structure=="binary") sum(x$outcome) else NA); emit("zero_variance_adjustments_dropped", length(zero_variance_adjustments))
auc <- function(y,p) { positive <- y==1; n_pos <- sum(positive); n_neg <- sum(!positive); if(!n_pos||!n_neg) return(NA); ranks <- rank(p, ties.method="average"); (sum(ranks[positive])-n_pos*(n_pos+1)/2)/(n_pos*n_neg) }
if (family == "association") {
  modifiers <- grep("^effect_modifier_",names(x),value=TRUE); model_terms <- candidate_columns
  if(length(modifiers)) model_terms <- unique(c(model_terms,paste0("exposure:",modifiers[[1]])))
  formula <- reformulate(model_terms, "outcome"); model <- if(outcome_structure=="binary") glm(formula,data=x,family=binomial()) else lm(formula,data=x)
  primary <- coef(model)[["exposure"]]; se <- sqrt(diag(vcov(model)))[["exposure"]]
  adjusted <- length(candidate_columns) > 1
  method <- if(outcome_structure=="binary") if(adjusted) "multivariable_logistic_regression" else "logistic_regression" else if(adjusted) "multivariable_linear_regression" else "linear_regression"
  emit("method", method); emit("estimate", primary); emit("ci_lower", primary-1.96*se); emit("ci_upper", primary+1.96*se); emit("effect_scale", if(outcome_structure=="binary") "log_odds_ratio" else "mean_difference"); emit("converged", if(is.null(model$converged)) 1 else as.integer(model$converged)); emit("parameters", length(coef(model))); emit("events_per_parameter", if(outcome_structure=="binary") sum(x$outcome)/length(coef(model)) else NA)
  if (outcome_structure == "binary" && exposure_is_binary) {
    exposed <- x$exposure == 1; n1 <- sum(exposed); n0 <- sum(!exposed); e1 <- sum(x$outcome[exposed]); e0 <- sum(x$outcome[!exposed]); p1 <- e1/n1; p0 <- e0/n0; rd <- p1-p0; rd_se <- sqrt(p1*(1-p1)/n1+p0*(1-p0)/n0)
    emit("exposed",n1); emit("unexposed",n0); emit("exposed_events",e1); emit("unexposed_events",e0); emit("risk_exposed",p1); emit("risk_unexposed",p0); emit("risk_difference",rd); emit("risk_difference_ci_lower",rd-1.96*rd_se); emit("risk_difference_ci_upper",rd+1.96*rd_se)
  }
  crude <- if(outcome_structure=="binary") glm(outcome~exposure,data=x,family=binomial()) else lm(outcome~exposure,data=x); emit("sensitivity_estimate", coef(crude)[["exposure"]]); emit("sensitivity", "crude_model")
  if(length(modifiers)) { interaction_name <- paste0("exposure:",modifiers[[1]]); beta <- coef(model)[[interaction_name]]; interaction_se <- sqrt(diag(vcov(model)))[[interaction_name]]; emit("interaction_estimate",if(outcome_structure=="binary") exp(beta) else beta); emit("interaction_effect_scale",if(outcome_structure=="binary") "ratio_of_odds_ratios" else "difference_in_mean_differences"); emit("interaction_ci_lower",if(outcome_structure=="binary") exp(beta-1.96*interaction_se) else beta-1.96*interaction_se); emit("interaction_ci_upper",if(outcome_structure=="binary") exp(beta+1.96*interaction_se) else beta+1.96*interaction_se) }
} else if (family == "prediction") {
  predictors <- intersect(grep("^predictor_", names(x), value=TRUE), candidate_columns); if(!length(predictors)||outcome_structure!="binary") stop("binary prediction requires predictors")
  validation <- seq_len(nrow(x)) %% 5 == 0; development <- x[!validation,,drop=FALSE]; test <- x[validation,,drop=FALSE]; model <- glm(reformulate(predictors,"outcome"),data=development,family=binomial()); p <- predict(model,newdata=test,type="response")
  predicted <- as.integer(p >= .5); calibration <- glm(test$outcome ~ qlogis(pmin(pmax(p,.000001),.999999)), family=binomial())
  emit("method","logistic_prediction_deterministic_split"); emit("development",nrow(development)); emit("validation",nrow(test)); emit("validation_events",sum(test$outcome)); emit("auroc",auc(test$outcome,p)); emit("brier",mean((test$outcome-p)^2)); emit("sensitivity_at_0_5",if(sum(test$outcome==1)) mean(predicted[test$outcome==1]==1) else NA); emit("specificity_at_0_5",if(sum(test$outcome==0)) mean(predicted[test$outcome==0]==0) else NA); emit("calibration_intercept",coef(calibration)[[1]]); emit("calibration_slope",coef(calibration)[[2]]); emit("converged",as.integer(model$converged)); emit("parameters",length(coef(model))); emit("events_per_parameter",sum(development$outcome)/length(coef(model))); emit("sensitivity_estimate",auc(development$outcome,predict(model,type="response"))); emit("sensitivity","development_apparent_auc")
} else if (family == "treatment_effect") {
  covariates <- intersect(grep("^(covariate|effect_modifier)_",names(x),value=TRUE), candidate_columns); if(!length(covariates)||!outcome_structure %in% c("binary","continuous")||length(unique(x$exposure))!=2) stop("treatment effect requires binary treatment and pretreatment covariates")
  ps_model <- glm(reformulate(covariates,"exposure"),data=x,family=binomial()); ps <- pmin(pmax(predict(ps_model,type="response"),.01),.99); prevalence <- mean(x$exposure); w <- ifelse(x$exposure==1,prevalence/ps,(1-prevalence)/(1-ps)); q <- quantile(w,c(.01,.99)); w <- pmin(pmax(w,q[[1]]),q[[2]]); wm <- function(v,w) sum(v*w)/sum(w); rt <- wm(x$outcome[x$exposure==1],w[x$exposure==1]); ru <- wm(x$outcome[x$exposure==0],w[x$exposure==0])
  weighted_mean_variance <- function(v,w,mean_value) sum((w^2)*(v-mean_value)^2)/(sum(w)^2); effect_se <- sqrt(weighted_mean_variance(x$outcome[x$exposure==1],w[x$exposure==1],rt)+weighted_mean_variance(x$outcome[x$exposure==0],w[x$exposure==0],ru)); effect_lower <- rt-ru-1.96*effect_se; effect_upper <- rt-ru+1.96*effect_se; if(outcome_structure=="binary") { effect_lower <- max(-1,effect_lower); effect_upper <- min(1,effect_upper) }
  smd <- function(v) { treated <- x$exposure==1; numerator <- wm(v[treated],w[treated])-wm(v[!treated],w[!treated]); denominator <- sqrt((var(v[treated])+var(v[!treated]))/2); ifelse(is.finite(denominator)&&denominator>0,abs(numerator/denominator),0) }; max_smd <- max(vapply(covariates,function(name)smd(x[[name]]),numeric(1)))
  emit("method",if(outcome_structure=="continuous") if(length(grep("^effect_modifier_",names(x),value=TRUE))) "stabilized_iptw_continuous_with_effect_modification" else "stabilized_iptw_continuous" else if(length(grep("^effect_modifier_",names(x),value=TRUE))) "stabilized_iptw_with_effect_modification" else "stabilized_iptw"); emit("treated_outcome",rt); emit("untreated_outcome",ru); if(outcome_structure=="binary") { emit("risk_treated",rt); emit("risk_untreated",ru) } else { emit("mean_treated",rt); emit("mean_untreated",ru) }; emit("estimate",rt-ru); emit("ci_lower",effect_lower); emit("ci_upper",effect_upper); emit("ci_method","weighted_influence_function_normal_approximation"); emit("effect_scale",if(outcome_structure=="binary") "risk_difference" else "mean_difference"); emit("effective_sample_size",sum(w)^2/sum(w^2)); emit("propensity_minimum",min(ps)); emit("propensity_maximum",max(ps)); emit("maximum_weighted_smd",max_smd); emit("converged",as.integer(ps_model$converged)); q5 <- quantile(w,c(.05,.95)); w5 <- pmin(pmax(w,q5[[1]]),q5[[2]]); emit("sensitivity_estimate",wm(x$outcome[x$exposure==1],w5[x$exposure==1])-wm(x$outcome[x$exposure==0],w5[x$exposure==0])); emit("sensitivity","weight_truncation_5_95")
  modifiers <- grep("^effect_modifier_",names(x),value=TRUE)
  if(length(modifiers)) { modifier <- modifiers[[1]]; interaction_formula <- reformulate(c("exposure",modifier,paste0("exposure:",modifier)),"outcome"); interaction_model <- if(outcome_structure=="binary") glm(interaction_formula,data=x,family=quasibinomial(),weights=w) else lm(interaction_formula,data=x,weights=w); interaction_name <- paste0("exposure:",modifier); beta <- coef(interaction_model)[[interaction_name]]; se <- sqrt(diag(vcov(interaction_model)))[[interaction_name]]; emit("interaction_estimate",if(outcome_structure=="binary") exp(beta) else beta); emit("interaction_effect_scale",if(outcome_structure=="binary") "ratio_of_odds_ratios" else "difference_in_mean_differences"); emit("interaction_ci_lower",if(outcome_structure=="binary") exp(beta-1.96*se) else beta-1.96*se); emit("interaction_ci_upper",if(outcome_structure=="binary") exp(beta+1.96*se) else beta+1.96*se); levels <- sort(unique(x[[modifier]])); if(length(levels)==2) for(i in seq_along(levels)) { level <- levels[[i]]; display_level <- if(length(category_labels[[modifier]])) category_labels[[modifier]][[level+1]] else level; rows <- x[[modifier]]==level; treated <- rows & x$exposure==1; untreated <- rows & x$exposure==0; if(any(treated)&&any(untreated)) { treated_value <- wm(x$outcome[treated],w[treated]); untreated_value <- wm(x$outcome[untreated],w[untreated]); stratum_effect <- treated_value-untreated_value; stratum_se <- sqrt(weighted_mean_variance(x$outcome[treated],w[treated],treated_value)+weighted_mean_variance(x$outcome[untreated],w[untreated],untreated_value)); stratum_lower <- stratum_effect-1.96*stratum_se; stratum_upper <- stratum_effect+1.96*stratum_se; if(outcome_structure=="binary") { stratum_lower <- max(-1,stratum_lower); stratum_upper <- min(1,stratum_upper) }; emit(paste0("stratum_",i,"_level"),display_level); emit(paste0("stratum_",i,"_treated_outcome"),treated_value); emit(paste0("stratum_",i,"_untreated_outcome"),untreated_value); emit(paste0("stratum_",i,"_effect"),stratum_effect); emit(paste0("stratum_",i,"_ci_lower"),stratum_lower); emit(paste0("stratum_",i,"_ci_upper"),stratum_upper); } } }
} else stop("unsupported study family")
